require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/ol_schema.php';require_login();require_premium();ensure_ol_schema();if(!in_array(user_grade_number(),[10,11],true)){redirect('student/dashboard.php');}verify_csrf();$qid=filter_input(INPUT_POST,'question_id',FILTER_VALIDATE_INT);$answer=trim((string)($_POST['student_answer']??''));$q=$qid?query_one('SELECT q.*,p.subject_id,p.year FROM ol_paper_questions q JOIN ol_papers p ON p.id=q.paper_id WHERE q.id=? AND p.status=1','i',[$qid]):null;if(!$q||$answer===''){redirect('student/dashboard.php');}$db=db();$st=$db->prepare('INSERT INTO ol_question_attempts(user_id,paper_question_id,student_answer) VALUES(?,?,?)');$uid=(int)user()['id'];$st->bind_param('iis',$uid,$qid,$answer);$st->execute();$_SESSION['ol_feedback']='Your answer was saved. Use the O/L AI Tutor for hints and improvement feedback.';redirect('ol-kuppiya/paper.php?subject_id='.$q['subject_id'].'&year='.$q['year']);
